import React, { useState } from "react";
import "./Header.css";
import more from "../assets/more.png";
import App from "./spline.jsx";
import AnchorLink from "react-anchor-link-smooth-scroll";
function Header() {
  const [clicked, setclicked] = useState("");
  const [activate, setActivate] = useState(false);
  function Activation() {
    activate ? setActivate(false) : setActivate(true);
  }

  return (
    <header>
      <div id="Header" className="header">
        <div className="Nav_bar">
          <div className="container">
            <nav>
              <div>
                <AnchorLink href="#Header">
                  <h2 className="heading" onClick={() => setclicked("")}>
                    Portfolio.
                  </h2>
                </AnchorLink>
              </div>

              <div className="Lists">
                <ul className={activate ? "list_items" : "new_class"}>
                  <li
                    onClick={() => setclicked("About")}
                    className="link_lists"
                  >
                    <AnchorLink
                      offset={50}
                      href="#About"
                      className={clicked === "About" ? "active" : "a"}
                    >
                      About
                    </AnchorLink>
                  </li>
                  <li
                    onClick={() => setclicked("Skills")}
                    className="link_lists"
                  >
                    <AnchorLink
                      offset={50}
                      href="#Skills"
                      className={clicked === "Skills" ? "active" : "a"}
                    >
                      Skills
                    </AnchorLink>
                  </li>
                  <li
                    onClick={() => setclicked("Projects")}
                    className="link_lists"
                  >
                    <AnchorLink
                      offset={50}
                      href="#Projects"
                      className={clicked === "Projects" ? "active" : "a"}
                    >
                      Projects
                    </AnchorLink>
                  </li>
                  <li
                    onClick={() => setclicked("Contacts")}
                    className="link_lists"
                  >
                    <AnchorLink
                      offset={50}
                      href="#Contacts"
                      className={clicked === "Contacts" ? "active" : "a"}
                    >
                      Contacts
                    </AnchorLink>
                  </li>
                </ul>

                <img src={more} className="nav_icon" onClick={Activation}></img>
              </div>
            </nav>
          </div>
        </div>
        <div>
          <div className="intro">
            <div className="wrap">
              <div className="border_left"><div className="circle"></div></div>
              <div className="descriptipn">
                <h1 className="info">
                  Hello , I ' m <span className="name">Aryan </span>
                </h1>
                <p className="title">I ' m web and app developer.</p>
              </div>
            </div>

            <div className="Text_box">
              <App />
            </div>
          </div>
        </div>
      </div>
    </header>
  );
}
export default Header;
