import React from "react";
import './Skill.css';
import Progressbar from "../components/progressbar";
import css from "../assets/icons/css.png";
import html from "../assets/icons/html.png";
import javascript from "../assets/icons/javascript.png";
import nodejs from "../assets/icons/nodejs.png";
import react from "../assets/icons/react.png";
import postgresql from "../assets/icons/sql.png";
import Technologies from "../components/techstacks";

function Skills(){

    return(
      <div className="Skills" id="Skills">
          <h1 className="page_heading">Skills</h1><hr className="line"></hr>
          <div className="about_skill">
                <p className="about_Text"> In my Web developement journey I have learned a bunch of programming languages and Different Technologies . As a  web-developer I have adequate knowlwdge of  front-end technologies like HTML, CSS, and JavaScript, to back-end languages such as  Node.js, and Java.I am proficient in frameworks like React , and I have a solid understanding of database management with systems like SQL and PostGreSQL. </p>
          </div>
          <div className="stuff">
            <div className="stuff_wrap">
            <div className="tech_box">
                  <Progressbar source={css} tech="CSS"/>
                  <div className="bar">
                  <div className="progress_line1"></div>
                  </div>
                  
              </div>
              <div className="tech_box">
                  <Progressbar source={html} tech="HTML"/>
                  <div className="bar">
                    <div className="progress_line"></div>
                  </div>
                  
              </div>
              <div className="tech_box">
                  <Progressbar source={javascript} tech="JS"/>
                  <div className="bar">
                  <div className="progress_line2"></div>
                  </div>
                  
              </div>
            </div>
             
          </div>
          <h1 className="Tech_head">Tech Stack</h1>
          <div className="techs">
            <div className="img_wrap">
            <div className="Images_box">
            <Technologies image={css}/>
            <Technologies image={html}/>
            <Technologies image={javascript}/>
            <Technologies image={react}/>
            <Technologies image={nodejs}/>
            <Technologies image={postgresql}/>

            </div>
            </div>
           
          </div>
          
      </div>

    );
}
export default Skills;