import React from "react";
import './pw.css';

function Projext_wrap(props){

    return(
       <div className="Projext_wrap">
          <img src={props.source} alt="" className="projectimage"/>
          <div className="probox">
            <h2 className="protitle">{props.title}</h2>
            <p className="prodes">{props.description}</p>
          </div>
       </div>
    );
}
export default Projext_wrap;